from pathlib import Path
import base64,json,html
root=Path('work/ABC_SmartPath');shots=root/'evidence/screenshots'
steps=[('The training enquiry','home.png','Start with a useful training conversation. ABC and its catalogue are fictional interview data.'),('Local AI recommendations','finder-live.png','Recorded live Qwen response. The enquiry is for online AI training for 15 beginners within six weeks.'),('Three eligible options','recommendations.png','Actual neural retrieval ranked Generative AI at Work, AI for Business Teams and Responsible AI Adoption Workshop. Course facts come from structured records.'),('Value before contact','lead-saved.png','Jordan Browser Demo requested a quote and gave service contact permission. Marketing remained unticked. The enquiry persisted in SQLite.'),('A stored opportunity','dashboard.png','The staff dashboard displays actual stored demonstration records. Priority uses transparent operational rules.'),('Priority and experiment','lead-detail.png','High priority reflects intent, urgency and cohort size. The separate 0.178 experimental score comes from a synthetic-only trained pipeline and has no validated real conversion meaning.'),('Staff edit and review','approval-review.png','A real local-model quote draft reached the approval queue. Staff shortened it, removed an unnecessary question and saved the edit before approving.'),('Controlled action','outbox.png','The approved edited message appears in the persistent local outbox. No message was sent externally. The API test also verified due-only reminders, duplicate suppression and stop-state cancellation.')]
data=[{'title':t,'note':n,'image':'data:image/png;base64,'+base64.b64encode((shots/f).read_bytes()).decode()} for t,f,n in steps]
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ABC SmartPath · Recorded fallback</title><style>*{box-sizing:border-box}body{margin:0;background:#10172a;color:#f8fafc;font:18px/1.5 system-ui}header,footer{padding:18px 4vw;display:flex;align-items:center;justify-content:space-between;gap:20px}header{border-bottom:1px solid #3a4155}small{color:#d6c6ff}.label{color:#ffd5b5;font-weight:700;font-size:13px;letter-spacing:1px}main{max-width:1280px;margin:auto;padding:10px 4vw}h1{font-size:30px;margin:12px 0}p{min-height:62px;max-width:1100px;color:#dce0ed}img{display:block;width:100%;max-height:65vh;object-fit:contain;background:#f9f8f5;border-radius:8px}button{font:inherit;background:#e9b79f;border:0;border-radius:8px;padding:10px 22px;cursor:pointer;color:#182035}button:disabled{opacity:.4;cursor:default}#count{color:#cbbbed}a{color:#d6c6ff}@media print{button{display:none}img{max-height:70vh}}</style><header><strong>ABC SmartPath</strong><span class="label">RECORDED SCREENSHOTS · NO LIVE AI</span></header><main><small id="count"></small><h1 id="title"></h1><p id="note"></p><img id="shot" alt="Recorded application screenshot"></main><footer><button id="prev">Previous</button><small>Works offline. Use left/right arrow keys. Recorded 24 October 2026.</small><button id="next">Next</button></footer><script>const steps=DATA;let i=0;function show(){document.getElementById('count').textContent=`${i+1} / ${steps.length}`;document.getElementById('title').textContent=steps[i].title;document.getElementById('note').textContent=steps[i].note;document.getElementById('shot').src=steps[i].image;document.getElementById('prev').disabled=i===0;document.getElementById('next').disabled=i===steps.length-1}function move(d){i=Math.max(0,Math.min(steps.length-1,i+d));show()}document.getElementById('prev').onclick=()=>move(-1);document.getElementById('next').onclick=()=>move(1);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)});show()</script></html>'''.replace('DATA',json.dumps(data))
(root/'docs/Offline_Demo.html').write_text(page)
assert len(data)==8 and 'http://' not in page and 'https://' not in page
(root/'evidence/browser-journey.json').write_text(json.dumps({'type':'manual browser verification through actual UI','passed':True,'steps':['Home course data loaded','Guided enquiry submitted without contact','Three live recommendations displayed','Quote capture service consent on marketing off','Saved lead reference displayed','Staff token login','Stored lead and requirements displayed','High operational priority and separate EXPERIMENTAL score','Real AI quote draft prepared','Staff edit saved','Approval moved edited message to local outbox'],'contact':'Jordan Browser Demo / jordan@example.com (synthetic)','screenshot_files':[f for _,f,_ in steps],'limits':'One desktop browser journey. No automated cross-browser, mobile or accessibility audit.'},indent=2))
print('Created standalone offline replay', (root/'docs/Offline_Demo.html').stat().st_size,'bytes')
